import justPick from"just-pick";import{vToken,vAdmin}from"../action/api-middleware.js";import*as friendlyLinkServer from"../service/friendly-link.js";import{PublicReturn}from"../common/public-return.js";import{friendlyLinkAddValidatorFn,friendlyLinkUpdateValidatorFn}from"../action/verified-option.js";import{createUuid}from"../common/uuid-tools.js";import{toBoolean}from"../common/other-tools.js";export function createRouter(e){e.get("/friendly-link/list",{preHandler:vToken},async function(e,n){const i=e.query||{},t=Math.abs(parseInt(i.page))||1,r=Math.abs(parseInt(i.size))||10,d={};Object.prototype.hasOwnProperty.call(i,"name")&&""!==i.name&&(d.name=i.name),Object.prototype.hasOwnProperty.call(i,"link")&&""!==i.link&&(d.link=i.link),Object.prototype.hasOwnProperty.call(i,"hidden")&&""!==i.hidden&&(d.hidden=String(toBoolean(i.hidden)));const o=await friendlyLinkServer.list({page:t,size:r,sortBy:[{desc:e=>e.initDate}],searchBy:d});n.send(new PublicReturn(200,"数据列表",{list:o.list,total:o.total,page:t,size:r}))}),e.get("/friendly-link/info/:uId",{preHandler:vToken},async function(e,n){const i=e.params||{},t=await friendlyLinkServer.find(e=>e.uId===i.uId);t?n.send(new PublicReturn(200,"成功",t)):n.code(404).send(new PublicReturn(404,"获取失败: 什么也没找到"))}),e.post("/friendly-link/add",{preHandler:vAdmin},async function(e,n){const i=justPick(e.body||{},["name","link","icon","content","hidden"]),t=friendlyLinkAddValidatorFn(i);if(t)return void n.code(400).send(new PublicReturn(400,t));await friendlyLinkServer.find(e=>e.name===i.name)?n.code(409).send(new PublicReturn(409,"添加失败: 重复数据")):(i.uId=createUuid(),i.initDate=(new Date).getTime(),await friendlyLinkServer.add(i),n.send(new PublicReturn(200,"成功",i)))}),e.put("/friendly-link/update",{preHandler:vAdmin},async function(e,n){const i=justPick(e.body||{},["uId","link","icon","content","hidden"]),t=friendlyLinkUpdateValidatorFn(i);if(t)return void n.code(400).send(new PublicReturn(400,t));const r=await friendlyLinkServer.find(e=>e.uId===i.uId);r?(i.updateDate=(new Date).getTime(),await friendlyLinkServer.update(r,i),n.send(new PublicReturn(200,"成功",i))):n.code(404).send(new PublicReturn(404,"修改失败: 未找到相应数据"))}),e.delete("/friendly-link/:ids",{preHandler:vAdmin},async function(e,n){const i=((e.params||{}).ids||"").split(",");if(0==i.length)return void n.code(400).send(new PublicReturn(400,"参数不能为空"));const t=await friendlyLinkServer.filter(e=>i.includes(e.uId));await friendlyLinkServer.delete_(t),n.send(new PublicReturn(200,"成功"))})}